<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function sw_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())sw_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))sw_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$role=(string)$_SESSION['role'];$allowed=['hr','admin','director','sub_director','headteacher'];if(!in_array($role,$allowed,true))sw_json(403,['ok'=>false,'message'=>'Your role cannot view staff workloads.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);if(!$school)sw_json(422,['ok'=>false,'message'=>'Choose a school.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())sw_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$roles="'admin','director','sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'";
$q=$db->prepare("SELECT u.id user_id,u.name,u.role,COALESCE((SELECT COUNT(*) FROM teacher_assignments a WHERE a.user_id=u.id AND a.school_id=m.school_id AND a.active=1),0) active_assignments,COALESCE((SELECT COUNT(*) FROM class_timetable_entries t WHERE t.teacher_id=u.id AND t.school_id=m.school_id AND t.status='published'),0) published_periods,COALESCE((SELECT SUM(TIME_TO_SEC(TIMEDIFF(t.ends_at,t.starts_at))/60) FROM class_timetable_entries t WHERE t.teacher_id=u.id AND t.school_id=m.school_id AND t.status='published'),0) scheduled_weekly_minutes,COALESCE((SELECT COUNT(*) FROM lesson_plans l WHERE l.teacher_id=u.id AND l.school_id=m.school_id AND l.status='submitted'),0) lesson_plans_for_review FROM school_memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=? AND u.status='active' AND u.role IN ($roles) ORDER BY u.name");$q->execute([$school]);sw_json(200,['ok'=>true,'data'=>['staff'=>$q->fetchAll(),'school_id'=>(int)$school]]);